test('addLine and removeLine work together', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = invoiceResult.value;

  // Add a line
  let result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);

  // Add another
