  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 3);

  // Remove one
  result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, true);
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

test('addLine merges across multiple operations', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = invoiceResult.value;

  let result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  invoice = result.value;
  assert.equal(invoice.lines[0].qty, 8);

  result = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });
