    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-1-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
