    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 }, // 85000, 5% discount = 4250
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }, // 47500, explicit 0% = 0
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // subtotal: 85000 + 47500 = 132500
  // discount: 4250 + 0 = 4250
  // total: 132500 - 4250 = 128250
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.total, 128250);
});

