test('invoiceTotals with real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // C-001 is gold tier, so lines get 5% discount
  // DES-HOUR: 10 * 8500 = 85000, discount 5% = 4250, after discount 80750, VAT 21% = 16957.50 = 16958
  // DEV-HOUR: 5 * 9500 = 47500, discount 5% = 2375, after discount 45125, VAT 21% = 9476.25 = 9476
  // Total discount: 6625, Total VAT: 26434
  // Total: 132500 - 6625 + 26434 = 152309
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 6625);
  assert.equal(totals.vat, 26434);
  assert.equal(totals.total, 152309);
});

